342	fn list_feedback(
343	    store: &FeedbackStore,
344	    status: Option<String>,
345	    tag: Option<String>,
346	    all: bool,
347	    ui: &mut dyn UserInterface,
348	) -> Result<i32> {
349	    let entries = if let Some(status_str) = status {
350	        let status = match status_str.as_str() {
351	            "open" => FeedbackStatus::Open,
352	            "resolved" => FeedbackStatus::Resolved,
353	            "wontfix" => FeedbackStatus::WontFix,
354	            "inprogress" | "in_progress" => FeedbackStatus::InProgress,
355	            _ => {
356	                ui.error(&format!("Unknown status: {}", status_str));
357	                return Ok(1);
358	            }
359	        };
360	        store.list_by_status(status)?
361	    } else if let Some(tag) = tag {
362	        store.list_by_tag(&tag)?
363	    } else if all {
364	        store.list_all()?
365	    } else {
366	        // Default: show open only
367	        store.list_by_status(FeedbackStatus::Open)?
368	    };
369	
370	    if entries.is_empty() {
371	        ui.message("No feedback entries found");
372	        return Ok(0);
373	    }
374	
375	    ui.message(&format!("{} feedback entries:\n", entries.len()));
376	    for entry in entries {
377	        let status_icon = match entry.status {
378	            FeedbackStatus::Open => "[ ]",
379	            FeedbackStatus::InProgress => "[~]",
380	            FeedbackStatus::Resolved => "[x]",
381	            FeedbackStatus::WontFix => "[-]",
382	        };
383	        let tags = if entry.tags.is_empty() {
384	            String::new()
385	        } else {
386	            format!(" [{}]", entry.tags.join(", "))
387	        };
388	        let session = entry
389	            .session_id
390	            .map(|s| format!(" ({})", s))
391	            .unwrap_or_default();
392	
393	        ui.message(&format!(
394	            "{} {} {}{}{}",
395	            status_icon, entry.id, entry.message, tags, session
396	        ));
397	    }
398	
399	    Ok(0)
400	}
