402	fn resolve_feedback(
403	    store: &FeedbackStore,
404	    id: &str,
405	    note: Option<String>,
406	    ui: &mut dyn UserInterface,
407	) -> Result<i32> {
408	    let resolution = note.unwrap_or_else(|| "Resolved".to_string());
409	
410	    let found = store.update(id, |entry| {
411	        entry.resolve(&resolution);
412	    })?;
413	
414	    if found {
415	        ui.success(&format!("Resolved {}", id));
416	        Ok(0)
417	    } else {
418	        ui.error(&format!("Feedback {} not found", id));
419	        Ok(1)
420	    }
421	}
422	
423	fn show_session_feedback(
424	    store: &FeedbackStore,
425	    session_id: Option<String>,
426	    ui: &mut dyn UserInterface,
427	) -> Result<i32> {
428	    let session_store = SessionStore::new(session_store_path());
429	
430	    let session = if let Some(id_str) = session_id {
431	        SessionId::parse(&id_str)
432	    } else {
433	        session_store.get_latest()?.map(|s| s.id)
434	    };
435	
436	    let Some(sid) = session else {
437	        ui.message("No sessions found");
438	        return Ok(0);
439	    };
440	
441	    let entries = store.list_by_session(&sid)?;
442	    if entries.is_empty() {
443	        ui.message(&format!("No feedback for session {}", sid));
444	        return Ok(0);
445	    }
446	
447	    ui.message(&format!("Feedback for session {}:\n", sid));
448	    for entry in entries {
449	        ui.message(&format!("  {} {}", entry.id, entry.message));
450	    }
451	
452	    Ok(0)
453	}
