fn resolve_with_visited<F>(
    &self,
    config: &BivvyConfig,
    visited: &mut HashSet<String>,
    depth: usize,
    trust_check: &mut F,
) -> Result<BivvyConfig>
where
    F: FnMut(&str) -> Result<()>,
{
    if depth > self.max_depth {
        return Err(BivvyError::ConfigValidationError {
            message: format!(
                "Config extends depth exceeds maximum of {}",
                self.max_depth
            ),
        });
    }

    // If no extends, return config as-is
    let extends = match &config.extends {
        Some(e) if !e.is_empty() => e,
        _ => return Ok(config.clone()),
    };

    // Convert current config to Value for merging
    let config_value =
        serde_yaml::to_value(config).map_err(|e| BivvyError::SerializationError {
            format: "YAML",
            message: e.to_string(),
        })?;

    // Environment override blocks should replace entirely, not field-merge
    let leaf_keys = std::collections::HashSet::from(["environments"]);

    // Start with empty Value
    let mut merged = serde_yaml::Value::Mapping(serde_yaml::Mapping::new());

    // Process each base config in order
    for ext in extends {
        // Check for cycles
        if visited.contains(&ext.url) {
            return Err(BivvyError::CircularDependency {
                cycle: ext.url.clone(),
            });
        }
        visited.insert(ext.url.clone());

        // Check trust before fetching
        trust_check(&ext.url)?;

        // Fetch and parse base config
        let content = self.fetcher.fetch(&ext.url).map_err(|e| {
            BivvyError::FetchError {
                url: ext.url.clone(),
                message: e.to_string(),
            }
        })?;
        let base_config: BivvyConfig =
            serde_yaml::from_str(&content).map_err(|e| BivvyError::ConfigParseError {
                path: PathBuf::from(&ext.url),
                message: e.to_string(),
            })?;

        // Recursively resolve base's extends
        let resolved_base =
            self.resolve_with_visited(&base_config, visited, depth + 1, trust_check)?;

        // Convert to Value and merge
        let base_value = serde_yaml::to_value(&resolved_base).map_err(|e| {
            BivvyError::SerializationError {
                format: "YAML",
                message: e.to_string(),
            }
        })?;
        merged = deep_merge_with_leaves(&merged, &base_value, &leaf_keys);
    }

    // Finally merge the current config on top
    let final_value = deep_merge_with_leaves(&merged, &config_value, &leaf_keys);

    // Deserialize back to BivvyConfig
    let mut final_config: BivvyConfig =
        serde_yaml::from_value(final_value).map_err(|e| BivvyError::ConfigParseError {
            path: PathBuf::from("<merged extends>"),
            message: e.to_string(),
        })?;

    // Clear extends from final config (already resolved)
    final_config.extends = None;

    Ok(final_config)
}

