        let child_config: BivvyConfig = serde_yaml::from_str(&child_yaml).unwrap();

        let resolver = resolver_with_mock(&server);
        let resolved = resolver.resolve(&child_config).unwrap();

        // Child's app_name wins
        assert_eq!(resolved.app_name, Some("ChildApp".to_string()));

        // The ci environment block should be fully replaced by child
        let ci = &resolved.steps["setup"].scoping.environments["ci"];
        assert_eq!(
            ci.command,
            Some("child-ci-cmd".to_string()),
            "Child's ci command should replace parent's"
        );
        // Parent's env vars should be gone (block replaced, not deep-merged)
        assert!(
            !ci.env.contains_key("PARENT_VAR"),
            "Parent's ci env vars should not survive replacement"
        );

        // Parent's default command should still be inherited (not inside environments block)
        assert_eq!(
            resolved.steps["setup"].execution.command,
            Some("parent-default-cmd".to_string()),
            "Parent's default command should be inherited"
        );
    }

    #[test]
    fn extends_inherits_only_environments_when_unset() {
        let server = MockServer::start();

        let base_yaml = r#"
app_name: BaseApp
steps:
  db:
    command: "db-setup"
    only_environments:
      - dev
"#;

        server.mock(|when, then| {
            when.method(GET).path("/base.yml");
            then.status(200).body(base_yaml);
        });

        // Overlay doesn't mention only_environments
        let mut steps = std::collections::HashMap::new();
        steps.insert(
            "db".to_string(),
            super::super::schema::StepConfig {
                execution: ExecutionConfig {
                    command: Some("custom-cmd".to_string()),
                    ..Default::default()
                },
                ..Default::default()
            },
        );

        let config = BivvyConfig {
            extends: Some(vec![ExtendsConfig {
                url: server.url("/base.yml"),
            }]),
            steps,
            ..Default::default()
        };

        let resolver = resolver_with_mock(&server);
        let resolved = resolver.resolve(&config).unwrap();

        // Command overridden
        assert_eq!(
            resolved.steps["db"].execution.command,
            Some("custom-cmd".to_string())
        );
        // only_environments inherited from base
        assert_eq!(
            resolved.steps["db"].scoping.only_environments,
            vec!["dev".to_string()]
        );
    }
}

