    let ttl = ttl.trim().to_lowercase();

    let parse_num = |s: &str| -> Result<i64> {
        s.parse().map_err(|e: std::num::ParseIntError| {
            crate::error::BivvyError::ConfigValidationError {
                message: format!("Invalid TTL number: {e}"),
            }
        })
    };

    if let Some(days) = ttl.strip_suffix('d') {
        Ok(Duration::days(parse_num(days)?))
    } else if let Some(hours) = ttl.strip_suffix('h') {
        Ok(Duration::hours(parse_num(hours)?))
    } else if let Some(mins) = ttl.strip_suffix('m') {
        Ok(Duration::minutes(parse_num(mins)?))
    } else if let Some(secs) = ttl.strip_suffix('s') {
        Ok(Duration::seconds(parse_num(secs)?))
    } else {
        // Assume seconds if no suffix
        Ok(Duration::seconds(parse_num(&ttl)?))
    }
}

