10	/// Allowed URL schemes for git clone operations.
11	///
12	/// Only secure transport protocols are permitted as defense-in-depth:
13	/// - `https://` -- encrypted HTTP transport
14	/// - `ssh://` -- SSH transport
15	/// - `git://` -- native git protocol
16	/// - `git@` -- SCP-style SSH shorthand (e.g. `git@github.com:org/repo.git`)
17	///
18	/// Rejected schemes include `file://` (local filesystem access), `ftp://`,
19	/// and plain `http://` (unencrypted, vulnerable to MITM).
20	pub fn validate_git_url(url: &str) -> Result<()> {
21	    // SCP-style shorthand: git@host:path
22	    if url.starts_with("git@") {
23	        return Ok(());
24	    }
25	
26	    const ALLOWED_SCHEMES: &[&str] = &["https://", "ssh://", "git://"];
27	
28	    for scheme in ALLOWED_SCHEMES {
29	        if url.starts_with(scheme) {
30	            return Ok(());
31	        }
32	    }
33	
34	    bail!(
35	        "Unsupported git URL scheme: {url}\n\
36	         Allowed schemes: https://, ssh://, git://, and git@ (SCP-style shorthand)"
37	    );
38	}
39	
40	/// Fetches templates from git repositories.
41	pub struct GitFetcher {
42	    /// Directory for cloned repositories.
43	    clone_dir: PathBuf,
44	}
45	
46	/// Information about a git fetch.
47	#[derive(Debug)]
48	pub struct GitFetchResult {
49	    /// Path to the fetched content.
50	    pub local_path: PathBuf,
51	    /// Current commit SHA.
52	    pub commit_sha: String,
53	}
54	
55	impl GitFetcher {
56	    /// Create a new git fetcher.
57	    pub fn new(clone_dir: impl Into<PathBuf>) -> Self {
58	        Self {
59	            clone_dir: clone_dir.into(),
60	        }
61	    }
62	
63	    /// Get the clone directory.
64	    pub fn clone_dir(&self) -> &PathBuf {
65	        &self.clone_dir
66	    }
67	
68	    /// Clone or update a repository.
69	    ///
70	    /// Validates the URL scheme before proceeding. Only `https://`, `ssh://`,
71	    /// `git://`, and `git@` SCP-style URLs are allowed.
72	    pub fn fetch(&self, url: &str, git_ref: Option<&str>) -> Result<GitFetchResult> {
73	        validate_git_url(url)?;
74	        self.fetch_unchecked(url, git_ref)
75	    }
76	
77	    /// Internal fetch without URL validation. Production callers must use
78	    /// [`fetch`](Self::fetch) so the URL scheme is checked first; this is
79	    /// exposed for integration tests that exercise local bare repositories.
80	    pub(crate) fn fetch_unchecked(
81	        &self,
82	        url: &str,
83	        git_ref: Option<&str>,
84	    ) -> Result<GitFetchResult> {
85	        let repo_path = self.repo_path(url);
86	
87	        if repo_path.exists() {
88	            self.update_repo(&repo_path, git_ref)?;
89	        } else {
90	            self.clone_repo(url, &repo_path, git_ref)?;
91	        }
92	
93	        let commit_sha = self.get_head_sha(&repo_path)?;
94	
95	        Ok(GitFetchResult {
96	            local_path: repo_path,
97	            commit_sha,
98	        })
99	    }
100	
101	    /// Check if a repository has new commits.
102	    ///
103	    /// Validates the URL scheme before proceeding.
104	    pub fn has_updates(&self, url: &str, git_ref: Option<&str>, current_sha: &str) -> Result<bool> {
105	        validate_git_url(url)?;
106	        self.has_updates_unchecked(url, git_ref, current_sha)
107	    }
108	
109	    /// Internal has_updates without URL validation.
110	    fn has_updates_unchecked(
111	        &self,
112	        url: &str,
113	        git_ref: Option<&str>,
114	        current_sha: &str,
115	    ) -> Result<bool> {
116	        let remote_sha = self.resolve_ref_unchecked(url, git_ref)?;
117	        Ok(remote_sha != current_sha)
118	    }
119	
120	    /// Get the current commit SHA for a ref using ls-remote.
121	    ///
122	    /// Validates the URL scheme before proceeding.
123	    pub fn resolve_ref(&self, url: &str, git_ref: Option<&str>) -> Result<String> {
124	        validate_git_url(url)?;
125	        self.resolve_ref_unchecked(url, git_ref)
126	    }
127	
128	    /// Internal resolve_ref without URL validation.
129	    fn resolve_ref_unchecked(&self, url: &str, git_ref: Option<&str>) -> Result<String> {
130	        let refspec = git_ref.unwrap_or("HEAD");
131	
132	        // Try the refspec directly, then with refs/heads/ and refs/tags/ prefixes.
133	        // Short refspecs like "v1.0" may not match "refs/tags/v1.0" in all git versions.
134	        let candidates = if refspec == "HEAD" {
135	            vec![refspec.to_string()]
136	        } else {
137	            vec![
138	                refspec.to_string(),
139	                format!("refs/heads/{refspec}"),
140	                format!("refs/tags/{refspec}"),
141	            ]
142	        };
143	
144	        for candidate in &candidates {
145	            let output = std::process::Command::new("git")
146	                .args(["ls-remote", url, candidate])
147	                .output()?;
148	
149	            if !output.status.success() {
150	                bail!(
151	                    "Failed to query remote: {}",
152	                    String::from_utf8_lossy(&output.stderr)
153	                );
154	            }
155	
156	            let stdout = String::from_utf8_lossy(&output.stdout);
157	            if let Some(sha) = stdout
158	                .lines()
159	                .next()
160	                .and_then(|line| line.split_whitespace().next())
161	            {
162	                return Ok(sha.to_string());
163	            }
164	        }
165	
166	        bail!("Could not resolve ref '{refspec}' from {url}")
167	    }
