251	/// Build a bare git repository under `parent` and seed it with the given
252	/// `(relative_path, yaml_content)` files, committed on `main`. Returns the
253	/// path to the bare repository so callers can use it as a clone source.
254	///
255	/// This is a shared test helper so multiple modules can exercise the Git
256	/// remote-template path without duplicating fixture setup.
257	#[cfg(test)]
258	pub(crate) fn create_bare_repo_with_templates(parent: &Path, files: &[(&str, &str)]) -> PathBuf {
259	    let bare_path = parent.join("templates-repo.git");
260	    let work_dir = parent.join("work");
261	    std::fs::create_dir_all(&work_dir).unwrap();
262	
263	    let status = std::process::Command::new("git")
264	        .args([
265	            "init",
266	            "--bare",
267	            "--initial-branch=main",
268	            bare_path.to_string_lossy().as_ref(),
269	        ])
270	        .status()
271	        .unwrap();
272	    assert!(status.success(), "bare init failed");
273	
274	    let status = std::process::Command::new("git")
275	        .args([
276	            "clone",
277	            bare_path.to_string_lossy().as_ref(),
278	            work_dir.to_string_lossy().as_ref(),
279	        ])
280	        .status()
281	        .unwrap();
282	    assert!(status.success(), "clone failed");
283	
284	    for (key, val) in [("user.name", "Test"), ("user.email", "test@test.com")] {
285	        std::process::Command::new("git")
286	            .args(["config", key, val])
287	            .current_dir(&work_dir)
288	            .status()
289	            .unwrap();
290	    }
291	
292	    for (rel_path, content) in files {
293	        let dest = work_dir.join(rel_path);
294	        if let Some(parent) = dest.parent() {
295	            std::fs::create_dir_all(parent).unwrap();
296	        }
297	        std::fs::write(&dest, content).unwrap();
298	    }
299	
300	    let status = std::process::Command::new("git")
301	        .args(["add", "."])
302	        .current_dir(&work_dir)
303	        .status()
304	        .unwrap();
305	    assert!(status.success(), "git add failed");
306	
307	    let status = std::process::Command::new("git")
308	        .args(["commit", "-m", "Seed templates"])
309	        .current_dir(&work_dir)
310	        .status()
311	        .unwrap();
312	    assert!(status.success(), "git commit failed");
313	
314	    let status = std::process::Command::new("git")
315	        .args(["push", "origin", "HEAD:main"])
316	        .current_dir(&work_dir)
317	        .status()
318	        .unwrap();
319	    assert!(status.success(), "git push failed");
320	
321	    bare_path
322	}
