            .append(&FeedbackEntry::new("bug").with_tags(vec!["bug"]))
            .unwrap();
        store
            .append(&FeedbackEntry::new("ux").with_tags(vec!["ux"]))
            .unwrap();

        // List by tag
        let result = list_feedback(&store, None, Some("bug".to_string()), false, &mut ui).unwrap();
        assert_eq!(result, 0);
    }

