if self.args.json {
    let json = serde_json::to_string_pretty(last_run)
        .map_err(|e| anyhow::anyhow!("JSON serialization failed: {e}"))?;
    ui.message(&json);
    return Ok(CommandResult::success());
}

let theme = BivvyTheme::new();
self.display_run(ui, last_run, &theme, "Last Run");

