            requirement: "node".into(),
            message: "Install command exited with code 1".into(),
        };
        let msg = err.to_string();
        assert!(msg.contains("node"));
        assert!(msg.contains("Install command exited with code 1"));
    }

    #[test]
    fn untrusted_url_displays_url_and_hint() {
        let err = BivvyError::UntrustedUrl {
            url: "https://example.com/config.yml".into(),
        };
        let msg = err.to_string();
        assert!(msg.contains("https://example.com/config.yml"));
        assert!(msg.contains("--trust"));
    }

    #[test]
    fn serialization_error_displays_format_and_message() {
        let err = BivvyError::SerializationError {
            format: "JSON",
            message: "unexpected end of input".into(),
        };
        let msg = err.to_string();
        assert!(msg.contains("JSON"));
        assert!(msg.contains("unexpected end of input"));
    }

    #[test]
    fn home_not_found_displays_message() {
        let err = BivvyError::HomeNotFound;
        assert!(err.to_string().contains("home directory"));
    }

    #[test]
    fn fetch_error_displays_url_and_message() {
        let err = BivvyError::FetchError {
            url: "https://example.com/config.yml".into(),
            message: "404 Not Found".into(),
        };
        let msg = err.to_string();
        assert!(msg.contains("https://example.com/config.yml"));
        assert!(msg.contains("404 Not Found"));
    }

    #[test]
    fn io_error_converts_from_std() {
        let io_err = std::io::Error::new(std::io::ErrorKind::NotFound, "file missing");
        let err: BivvyError = io_err.into();
        assert!(matches!(err, BivvyError::Io(_)));
    }

    #[test]
    fn result_type_alias_works() {
        fn returns_error() -> Result<()> {
            Err(BivvyError::ConfigValidationError {
                message: "test".into(),
            })
        }
        assert!(returns_error().is_err());
    }
}

